mapper.insert:
INSERT
  INTO
	   GAME (
			  GAME_ID
			, ROOM_ID
			, BAG_COUNT
			, WINNING_INDEX
			, CURRENT_PARTICIPANT_ID
			, TURN_DEADLINE
			)
VALUES
	   (
		 SEQ_GAME.NEXTVAL
	   , #{roomId}
	   , #{bagCount}
	   , #{winningIndex}
	   , #{currentParticipantId}
	   , SYSTIMESTAMP + NUMTODSINTERVAL(#{turnSeconds}, 'SECOND')
	   )

BEGIN

	INSERT
	  INTO
		   GAME_PARTICIPANT (
							  GAME_PARTICIPANT_ID
							, GAME_ID
							, PARTICIPANT_ID
							, TURN_ORDER
							)
	VALUES
		   (
			 SEQ_GAME_PARTICIPANT.NEXTVAL
		   , (
			   SELECT
					  GAME_ID
				 FROM
					  GAME
				WHERE
					  ROOM_ID = #{player.roomId}
			 )
		   , #{player.participantId}
		   , #{player.turnOrder}
		   );

END;
